// Offscreen Vulkan validation; no SDL, VideoOut calls, decoder or console connection.
#include <vulkan/vulkan.h>
#include "OmniHdrColour.h" // independent preserved CPU reference, test-only include
#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <cstring>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <vector>
static void check(VkResult r){if(r!=VK_SUCCESS)throw std::runtime_error("Vulkan result "+std::to_string(r));}
struct Image {VkImage image{};VkImageView view{};VkDeviceMemory memory{};};
struct Buffer {VkBuffer buffer{};VkDeviceMemory memory{};};
struct Context {
 VkInstance instance{};VkPhysicalDevice physical{};VkDevice device{};VkQueue queue{};uint32_t family{};
 VkCommandPool commandPool{};VkCommandBuffer command{};VkDescriptorSetLayout setLayout{};VkPipelineLayout layout{};
 VkDescriptorPool descriptorPool{};VkDescriptorSet set{};VkPipeline pipeline{};VkShaderModule shader{};VkSampler sampler{};
 std::vector<Image> images;std::vector<Buffer> buffers;
 uint32_t memoryType(uint32_t bits,VkMemoryPropertyFlags flags){VkPhysicalDeviceMemoryProperties p;vkGetPhysicalDeviceMemoryProperties(physical,&p);for(uint32_t i=0;i<p.memoryTypeCount;++i)if((bits&(1u<<i))&&(p.memoryTypes[i].propertyFlags&flags)==flags)return i;throw std::runtime_error("No matching memory type");}
 Buffer buffer(VkDeviceSize size,VkBufferUsageFlags usage){Buffer b;VkBufferCreateInfo c{VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO};c.size=size;c.usage=usage;c.sharingMode=VK_SHARING_MODE_EXCLUSIVE;check(vkCreateBuffer(device,&c,nullptr,&b.buffer));VkMemoryRequirements req;vkGetBufferMemoryRequirements(device,b.buffer,&req);VkMemoryAllocateInfo a{VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO};a.allocationSize=req.size;a.memoryTypeIndex=memoryType(req.memoryTypeBits,VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT|VK_MEMORY_PROPERTY_HOST_COHERENT_BIT);check(vkAllocateMemory(device,&a,nullptr,&b.memory));check(vkBindBufferMemory(device,b.buffer,b.memory,0));buffers.push_back(b);return b;}
 Image image(uint32_t w,uint32_t h,VkFormat format,bool output=false){Image i;VkImageCreateInfo c{VK_STRUCTURE_TYPE_IMAGE_CREATE_INFO};c.imageType=VK_IMAGE_TYPE_2D;c.format=format;c.extent={w,h,1};c.mipLevels=c.arrayLayers=1;c.samples=VK_SAMPLE_COUNT_1_BIT;c.tiling=VK_IMAGE_TILING_OPTIMAL;c.usage=output?(VK_IMAGE_USAGE_STORAGE_BIT|VK_IMAGE_USAGE_TRANSFER_SRC_BIT):(VK_IMAGE_USAGE_SAMPLED_BIT|VK_IMAGE_USAGE_TRANSFER_DST_BIT);c.sharingMode=VK_SHARING_MODE_EXCLUSIVE;check(vkCreateImage(device,&c,nullptr,&i.image));VkMemoryRequirements req;vkGetImageMemoryRequirements(device,i.image,&req);VkMemoryAllocateInfo a{VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO};a.allocationSize=req.size;a.memoryTypeIndex=memoryType(req.memoryTypeBits,0);check(vkAllocateMemory(device,&a,nullptr,&i.memory));check(vkBindImageMemory(device,i.image,i.memory,0));VkImageViewCreateInfo v{VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO};v.image=i.image;v.viewType=VK_IMAGE_VIEW_TYPE_2D;v.format=format;v.subresourceRange={VK_IMAGE_ASPECT_COLOR_BIT,0,1,0,1};check(vkCreateImageView(device,&v,nullptr,&i.view));images.push_back(i);return i;}
 void barrier(Image i,VkImageLayout old,VkImageLayout next,VkAccessFlags src,VkAccessFlags dst){VkImageMemoryBarrier b{VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER};b.srcAccessMask=src;b.dstAccessMask=dst;b.oldLayout=old;b.newLayout=next;b.srcQueueFamilyIndex=b.dstQueueFamilyIndex=VK_QUEUE_FAMILY_IGNORED;b.image=i.image;b.subresourceRange={VK_IMAGE_ASPECT_COLOR_BIT,0,1,0,1};vkCmdPipelineBarrier(command,VK_PIPELINE_STAGE_ALL_COMMANDS_BIT,VK_PIPELINE_STAGE_ALL_COMMANDS_BIT,0,0,nullptr,0,nullptr,1,&b);}
 void upload(Image i,uint32_t w,uint32_t h,const std::vector<uint8_t>& data){auto b=buffer(data.size(),VK_BUFFER_USAGE_TRANSFER_SRC_BIT);void* ptr;check(vkMapMemory(device,b.memory,0,data.size(),0,&ptr));memcpy(ptr,data.data(),data.size());vkUnmapMemory(device,b.memory);barrier(i,VK_IMAGE_LAYOUT_UNDEFINED,VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,0,VK_ACCESS_TRANSFER_WRITE_BIT);VkBufferImageCopy copy{};copy.imageSubresource={VK_IMAGE_ASPECT_COLOR_BIT,0,0,1};copy.imageExtent={w,h,1};vkCmdCopyBufferToImage(command,b.buffer,i.image,VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,1,&copy);barrier(i,VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL,VK_ACCESS_TRANSFER_WRITE_BIT,VK_ACCESS_SHADER_READ_BIT);}
 void clearFrames(){for(auto i:images){vkDestroyImageView(device,i.view,nullptr);vkDestroyImage(device,i.image,nullptr);vkFreeMemory(device,i.memory,nullptr);}images.clear();for(auto b:buffers){vkDestroyBuffer(device,b.buffer,nullptr);vkFreeMemory(device,b.memory,nullptr);}buffers.clear();}
 explicit Context(const char* path){VkApplicationInfo app{VK_STRUCTURE_TYPE_APPLICATION_INFO};app.pApplicationName="ExBox host presenter validation";app.apiVersion=VK_API_VERSION_1_1;VkInstanceCreateInfo ci{VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO};ci.pApplicationInfo=&app;check(vkCreateInstance(&ci,nullptr,&instance));uint32_t n=0;check(vkEnumeratePhysicalDevices(instance,&n,nullptr));if(!n)throw std::runtime_error("No Vulkan device");std::vector<VkPhysicalDevice> devs(n);check(vkEnumeratePhysicalDevices(instance,&n,devs.data()));physical=devs.front();VkPhysicalDeviceProperties props;vkGetPhysicalDeviceProperties(physical,&props);std::cout<<"device="<<props.deviceName<<'\n';vkGetPhysicalDeviceQueueFamilyProperties(physical,&n,nullptr);std::vector<VkQueueFamilyProperties> qs(n);vkGetPhysicalDeviceQueueFamilyProperties(physical,&n,qs.data());while(family<n&&!(qs[family].queueFlags&VK_QUEUE_COMPUTE_BIT))++family;if(family==n)throw std::runtime_error("No compute queue");float priority=1;VkDeviceQueueCreateInfo q{VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO};q.queueFamilyIndex=family;q.queueCount=1;q.pQueuePriorities=&priority;VkDeviceCreateInfo dc{VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO};dc.queueCreateInfoCount=1;dc.pQueueCreateInfos=&q;check(vkCreateDevice(physical,&dc,nullptr,&device));vkGetDeviceQueue(device,family,0,&queue);
 VkCommandPoolCreateInfo cp{VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO};cp.queueFamilyIndex=family;cp.flags=VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT;check(vkCreateCommandPool(device,&cp,nullptr,&commandPool));VkCommandBufferAllocateInfo ca{VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO};ca.commandPool=commandPool;ca.level=VK_COMMAND_BUFFER_LEVEL_PRIMARY;ca.commandBufferCount=1;check(vkAllocateCommandBuffers(device,&ca,&command));
 std::array<VkDescriptorSetLayoutBinding,4> bindings{};for(uint32_t i=0;i<4;++i)bindings[i]={i,i==3?VK_DESCRIPTOR_TYPE_STORAGE_IMAGE:VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER,1,VK_SHADER_STAGE_COMPUTE_BIT,nullptr};VkDescriptorSetLayoutCreateInfo sl{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO};sl.bindingCount=4;sl.pBindings=bindings.data();check(vkCreateDescriptorSetLayout(device,&sl,nullptr,&setLayout));VkPushConstantRange push{VK_SHADER_STAGE_COMPUTE_BIT,0,48};VkPipelineLayoutCreateInfo pl{VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO};pl.setLayoutCount=1;pl.pSetLayouts=&setLayout;pl.pushConstantRangeCount=1;pl.pPushConstantRanges=&push;check(vkCreatePipelineLayout(device,&pl,nullptr,&layout));VkDescriptorPoolSize sizes[]={{VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER,3},{VK_DESCRIPTOR_TYPE_STORAGE_IMAGE,1}};VkDescriptorPoolCreateInfo dp{VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO};dp.maxSets=1;dp.poolSizeCount=2;dp.pPoolSizes=sizes;check(vkCreateDescriptorPool(device,&dp,nullptr,&descriptorPool));VkDescriptorSetAllocateInfo da{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO};da.descriptorPool=descriptorPool;da.descriptorSetCount=1;da.pSetLayouts=&setLayout;check(vkAllocateDescriptorSets(device,&da,&set));
 std::ifstream file(path,std::ios::binary|std::ios::ate);if(!file)throw std::runtime_error("Missing compiled shader");size_t bytes=size_t(file.tellg());if(!bytes||bytes%4)throw std::runtime_error("Invalid shader size");std::vector<uint32_t> code(bytes/4);file.seekg(0);file.read(reinterpret_cast<char*>(code.data()),bytes);VkShaderModuleCreateInfo sm{VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO};sm.codeSize=bytes;sm.pCode=code.data();check(vkCreateShaderModule(device,&sm,nullptr,&shader));VkComputePipelineCreateInfo pi{VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO};pi.layout=layout;pi.stage={VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO,nullptr,0,VK_SHADER_STAGE_COMPUTE_BIT,shader,"main",nullptr};check(vkCreateComputePipelines(device,VK_NULL_HANDLE,1,&pi,nullptr,&pipeline));VkSamplerCreateInfo sc{VK_STRUCTURE_TYPE_SAMPLER_CREATE_INFO};sc.magFilter=sc.minFilter=VK_FILTER_NEAREST;sc.mipmapMode=VK_SAMPLER_MIPMAP_MODE_NEAREST;sc.addressModeU=sc.addressModeV=sc.addressModeW=VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;check(vkCreateSampler(device,&sc,nullptr,&sampler));}
 ~Context(){if(device){vkDeviceWaitIdle(device);clearFrames();vkDestroySampler(device,sampler,nullptr);vkDestroyPipeline(device,pipeline,nullptr);vkDestroyShaderModule(device,shader,nullptr);vkDestroyPipelineLayout(device,layout,nullptr);vkDestroyDescriptorPool(device,descriptorPool,nullptr);vkDestroyDescriptorSetLayout(device,setLayout,nullptr);vkDestroyCommandPool(device,commandPool,nullptr);vkDestroyDevice(device,nullptr);}if(instance)vkDestroyInstance(instance,nullptr);}
};
struct Params{uint32_t w,h,depth,high,limited,matrix,hdr,reserved=0;float white=203,pad0=0,pad1=0,pad2=0;};static_assert(sizeof(Params)==48);
static std::vector<uint8_t> samples(size_t count,uint32_t code,int depth,bool high){std::vector<uint8_t> out(count*(depth==8?1:2));for(size_t i=0;i<count;++i){if(depth==8)out[i]=uint8_t(code);else{uint16_t v=uint16_t(code<<(high?6:0));memcpy(out.data()+i*2,&v,2);}}return out;}
static void run(Context& c,Params p,unsigned y,unsigned u,unsigned v,std::array<uint8_t,4> overlay){
 auto begin=std::chrono::steady_clock::now();check(vkResetCommandBuffer(c.command,0));VkCommandBufferBeginInfo bi{VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};check(vkBeginCommandBuffer(c.command,&bi));
 Image yy=c.image(p.w,p.h,p.depth==8?VK_FORMAT_R8_UNORM:VK_FORMAT_R16_UNORM),uv=c.image((p.w+1)/2,(p.h+1)/2,p.depth==8?VK_FORMAT_R8G8_UNORM:VK_FORMAT_R16G16_UNORM),ui=c.image(p.w,p.h,VK_FORMAT_R8G8B8A8_UNORM),out=c.image(p.w,p.h,VK_FORMAT_R32G32B32A32_SFLOAT,true);
 auto yd=samples(size_t(p.w)*p.h,y,p.depth,p.high),ud=samples(size_t((p.w+1)/2)*((p.h+1)/2)*2,u,p.depth,p.high);auto vd=samples(1,v,p.depth,p.high);size_t step=p.depth==8?1:2;for(size_t i=step;i<ud.size();i+=step*2)memcpy(ud.data()+i,vd.data(),step);std::vector<uint8_t> uiData(size_t(p.w)*p.h*4);for(size_t i=0;i<uiData.size();i+=4)memcpy(uiData.data()+i,overlay.data(),4);
 c.upload(yy,p.w,p.h,yd);c.upload(uv,(p.w+1)/2,(p.h+1)/2,ud);c.upload(ui,p.w,p.h,uiData);c.barrier(out,VK_IMAGE_LAYOUT_UNDEFINED,VK_IMAGE_LAYOUT_GENERAL,0,VK_ACCESS_SHADER_WRITE_BIT);
 Image imgs[]={yy,uv,ui,out};VkDescriptorImageInfo infos[4]{};VkWriteDescriptorSet writes[4]{};for(uint32_t i=0;i<4;++i){infos[i]={i==3?VK_NULL_HANDLE:c.sampler,imgs[i].view,i==3?VK_IMAGE_LAYOUT_GENERAL:VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL};writes[i].sType=VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;writes[i].dstSet=c.set;writes[i].dstBinding=i;writes[i].descriptorCount=1;writes[i].descriptorType=i==3?VK_DESCRIPTOR_TYPE_STORAGE_IMAGE:VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;writes[i].pImageInfo=&infos[i];}vkUpdateDescriptorSets(c.device,4,writes,0,nullptr);vkCmdBindPipeline(c.command,VK_PIPELINE_BIND_POINT_COMPUTE,c.pipeline);vkCmdBindDescriptorSets(c.command,VK_PIPELINE_BIND_POINT_COMPUTE,c.layout,0,1,&c.set,0,nullptr);vkCmdPushConstants(c.command,c.layout,VK_SHADER_STAGE_COMPUTE_BIT,0,sizeof p,&p);vkCmdDispatch(c.command,(p.w+7)/8,(p.h+7)/8,1);
 c.barrier(out,VK_IMAGE_LAYOUT_GENERAL,VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,VK_ACCESS_SHADER_WRITE_BIT,VK_ACCESS_TRANSFER_READ_BIT);size_t bytes=size_t(p.w)*p.h*4*sizeof(float);auto rb=c.buffer(bytes,VK_BUFFER_USAGE_TRANSFER_DST_BIT);VkBufferImageCopy copy{};copy.imageSubresource={VK_IMAGE_ASPECT_COLOR_BIT,0,0,1};copy.imageExtent={p.w,p.h,1};vkCmdCopyImageToBuffer(c.command,out.image,VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,rb.buffer,1,&copy);check(vkEndCommandBuffer(c.command));VkSubmitInfo submit{VK_STRUCTURE_TYPE_SUBMIT_INFO};submit.commandBufferCount=1;submit.pCommandBuffers=&c.command;check(vkQueueSubmit(c.queue,1,&submit,VK_NULL_HANDLE));check(vkQueueWaitIdle(c.queue));
 double expected[3];if(p.hdr){auto rgb=OmniMedia::Hdr::yuv10(y,u,v,!p.limited);rgb=OmniMedia::Hdr::overlay(rgb,overlay[0],overlay[1],overlay[2],overlay[3],p.white);for(int i=0;i<3;++i)expected[i]=double((rgb>>(i*10))&1023)/1023.;}else{double kr=p.matrix==0?.299:.2126,kb=p.matrix==0?.114:.0722,kg=1-kr-kb;double l=(double(y)-(p.limited?16:0))/(p.limited?219:255),cb=(double(u)-128)/(p.limited?224:255),cr=(double(v)-128)/(p.limited?224:255);double values[]={l+2*(1-kr)*cr,l-2*kb*(1-kb)/kg*cb-2*kr*(1-kr)/kg*cr,l+2*(1-kb)*cb};for(int i=0;i<3;++i)expected[i]=std::clamp(values[i],0.,1.)*(1-overlay[3]/255.)+overlay[i]/255.;}
 void* mapped;check(vkMapMemory(c.device,rb.memory,0,bytes,0,&mapped));auto pixels=static_cast<const float*>(mapped);double maxError=0;for(size_t i=0;i<size_t(p.w)*p.h;++i){for(int j=0;j<3;++j){if(!std::isfinite(pixels[i*4+j]))throw std::runtime_error("Nonfinite output");maxError=std::max(maxError,std::abs(pixels[i*4+j]-expected[j]));}if(pixels[i*4+3]!=1)throw std::runtime_error("Alpha mismatch");}vkUnmapMemory(c.device,rb.memory);if(maxError>(p.hdr?2./1023.:.0001))throw std::runtime_error("Colour mismatch "+std::to_string(maxError));
 double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-begin).count();std::cout<<p.w<<'x'<<p.h<<" depth="<<p.depth<<" high="<<p.high<<" hdr="<<p.hdr<<" max_error="<<maxError<<" host_total_ms="<<ms<<'\n';c.clearFrames();
}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("shader path required");Context c(argv[1]);for(unsigned matrix:{0u,1u})for(unsigned limited:{0u,1u})run(c,{64,32,8,0,limited,matrix,0},120,80,200,{0,0,0,0});run(c,{64,32,8,0,1,1,0},16,128,128,{0,0,0,0});run(c,{64,32,8,0,1,1,0},235,128,128,{0,0,0,0});for(unsigned high:{0u,1u}){run(c,{64,32,10,high,1,2,1},512,380,600,{0,0,0,0});run(c,{64,32,10,high,1,2,1},512,380,600,{128,0,0,128});}run(c,{3840,2160,10,0,1,2,1},512,512,512,{0,0,0,0});std::cout<<"PASS 11 Vulkan image conversion/composition cases; not PS5 scanout or 4K60 proof\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
